{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C08", "C47", "C12", "C18", "C03", "C116"],
  "contradictory_card_ids": ["C27", "C160", "C171", "C163", "C178", "C206", "C237", "C239", "C240", "C249", "C235", "C224", "C250", "C238", "C253"],
  "prediction_basis_card_ids": ["C08", "C47", "C12", "C18", "C03"],
  "claims": [
    {
      "claim": "The closest fed-state reference context, KNI-272, gave absolute oral bioavailability of 36.4% as a post-prandial capsule in patients and 22.06% at a 4 mg/kg capsule dose, directly supporting F ≥ 20% for this peptidomimetic scaffold under fed conditions.",
      "card_ids": ["C08", "C47"]
    },
    {
      "claim": "Fed-state atazanavir (>90%) and paritaprevir tablet (52.6%) provide additional direct absolute-bioavailability outcomes above the threshold for related peptidomimetic protease-inhibitor scaffolds.",
      "card_ids": ["C12", "C18", "C03"]
    },
    {
      "claim": "KNI-272 syrup at 2 mg/kg gave 15.72%, showing formulation/dose dependence; the query formulation is unspecified, so this limits confidence but does not establish a class-level low outcome.",
      "card_ids": ["C27"]
    },
    {
      "claim": "L6 saquinavir records show high hepatic extraction (0.76–0.86 in dogs), hepatic clearance approaching liver blood flow, and CYP3A4-mediated metabolism, providing mechanistic evidence for first-pass loss that may apply to the shared decahydroisoquinoline/tert-butylamide core; however, these are indirect and do not quantify F for the query.",
      "card_ids": ["C237", "C239", "C240", "C249", "C235", "C224"]
    },
    {
      "claim": "L5 saquinavir P-gp efflux and intestinal CYP3A4 metabolism similarly indicate presystemic loss, but atazanavir is also a strong P-gp substrate with >90% fed F, so efflux/metabolism alone does not establish F < 20%.",
      "card_ids": ["C171", "C160", "C180", "C12", "C18"]
    },
    {
      "claim": "L4 saquinavir Caco-2 permeability was high (4.68 × 10^-5 cm/s), supporting adequate intrinsic intestinal permeability for the closely related scaffold.",
      "card_ids": ["C116"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C237", "C239", "C240", "C249", "C235", "C224", "C250", "C238", "C253"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific hepatic clearance or metabolic-stability data are available; L6 records are for saquinavir and other molecules.",
    "Query formulation and dose are unspecified; KNI-272 F ranges from 15.72% (syrup) to 36.4% (capsule).",
    "Fed-state effect on the query's solubility and dissolution is not directly measured.",
    "No query-specific P-gp/efflux or intestinal metabolism data are available.",
    "Species differences limit translation of dog hepatic extraction and rat microsomal clearance to human oral F."
  ],
  "decision_summary": "L6 hepatic-clearance records for saquinavir add credible mechanistic evidence for first-pass loss in the shared decahydroisoquinoline/tert-butylamide scaffold, weakening confidence, but they are indirect and do not overturn the direct fed-state absolute-bioavailability outcomes (KNI-272 capsule 36.4%/22.06%, atazanavir >90%, paritaprevir 52.6%) that support F ≥ 20%. Prediction remains high with low confidence."
}

